{
  "description": "The creature is a quadrupedal, horse-proportioned animal shown in right-facing profile standing on a small patch of sparse grass and dirt. Its overall body shape, head, legs and hooves are those of a horse, but almost the entire dorsal and lateral surface is covered in dense, overlapping, rounded scales in mottled brown and tan resembling pangolin armor. The scales cover the neck, back, sides, rump, outer surfaces of all four legs, the long tapering tail, and the forehead and crown between the ears. The face, muzzle, ears, and the ventral belly and inner upper legs retain short hair; the facial hair is brown with a dark muzzle and nostril, the belly and inner leg fur is pale cream to light tan, and the lower legs have a fringe of brown hair just above the hooves. The head is held at shoulder height with ears erect, and all four hooved feet are on the ground. The tail hangs vertically behind the hind legs.",
  "parts": [
    {
      "part": "head",
      "looks_like": "horse-like head with brown short hair, dark brown muzzle, large black nostril, dark eye with eyelid, lower lip and chin with short whiskers, forehead and crown covered with overlapping rounded brown scales",
      "where": "at the anterior end of the neck, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, brown horse ears with darker inner fur and pointed tips",
      "where": "on top of the head, emerging from the scaly covering on the crown"
    },
    {
      "part": "mane",
      "looks_like": "no hair mane; dorsal ridge of neck covered with overlapping brown scales forming a scaly crest where a mane would be",
      "where": "along the dorsal midline of the neck from behind the ears to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four long, slender horse-like legs, anterior and lateral surfaces densely covered with overlapping brown rounded scales, posterior and ventral upper portions with pale cream shaggy fur",
      "where": "beneath the trunk, two forelegs under the chest and two hind legs under the rump"
    },
    {
      "part": "feet",
      "looks_like": "four rounded, dark brown keratinous hooves, each with a short fringe of brown hair just above the hoof wall",
      "where": "at the distal ends of all four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "single long, narrow, tapering tail fully covered on all sides with overlapping brown rounded scales, pointed at the tip",
      "where": "extending from the posterior rump, hanging vertically down behind the hind legs"
    },
    {
      "part": "scales",
      "looks_like": "dense, overlapping, rounded keratinous scales in shades of brown and tan with darker brown margins, arranged in diagonal rows like armor",
      "where": "covering the neck, trunk, sides, rump, outer legs, tail, and forehead between the ears"
    },
    {
      "part": "plates",
      "looks_like": "the overlapping scales form continuous armor plates over the body",
      "where": "over the dorsal and lateral trunk, neck, legs and tail"
    },
    {
      "part": "markings",
      "looks_like": "pale cream to off-white shaggy fur on the ventral belly, chest, and inner upper legs contrasting with the brown scaly dorsum; brown hair on face and lower legs",
      "where": "on the underside of the body and inner legs, and on the face"
    }
  ],
  "attached_objects": [],
  "animals": [
    "horse",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
